# Kurs Mikrocontroller im Fahrzeug
from common import *

M1 = M("mcu.m1", 1, "Was ein Mikrocontroller ist", "Aufbau, Unterschied zu Prozessor und SoC, Takt und Kerne.", [
 L("mcu.m1.l1", "Ein Computer auf einem Chip", 5, [
  "Ein Mikrocontroller (MCU) vereint Prozessorkern, Programmspeicher, Arbeitsspeicher und Peripherie auf einem einzigen Chip. Er braucht kaum externe Bauteile und steuert direkt Sensoren und Aktoren.",
  "## Die Bausteine",
  "CPU-Kerne führen das Programm aus. Flash speichert Programm und Daten dauerhaft, RAM hält Variablen. Peripherie verbindet mit der Außenwelt: Analog-Digital-Wandler, Timer, Kommunikationsschnittstellen (CAN, LIN, Ethernet, SPI) und digitale Ein- und Ausgänge.",
  "## Mikrocontroller, Mikroprozessor, SoC",
  "Ein Mikroprozessor (MPU) hat schnelle Kerne, aber meist externen Speicher und läuft oft mit einem großen Betriebssystem wie Linux. Ein System-on-Chip (SoC) kombiniert viele Prozessoren, Grafik- und KI-Beschleuniger, etwa für Infotainment oder automatisiertes Fahren. Mikrocontroller sind dagegen auf Echtzeit, Zuverlässigkeit und direkte Ansteuerung optimiert."],
  ["MCU = Kerne + Flash + RAM + Peripherie auf einem Chip.", "MPU: externer Speicher, großes Betriebssystem; SoC: viele Recheneinheiten und Beschleuniger.", "MCU: Echtzeit, Zuverlässigkeit, direkte Ansteuerung."],
  [S_INF, S_ST],
  [card("Mikrocontroller (MCU)", "Chip mit Prozessorkern, Speicher und Peripherie für Steuerungsaufgaben."), card("SoC", "System-on-Chip: viele Prozessoren und Beschleuniger auf einem Chip, z. B. für Infotainment oder ADAS."), card("Peripherie", "Funktionsblöcke wie ADC, Timer, CAN oder SPI, die den Chip mit der Außenwelt verbinden.")],
  [mc("Was hat ein Mikrocontroller im Gegensatz zu einem typischen Mikroprozessor?", ["Speicher und Peripherie auf dem Chip", "Keine CPU", "Nur Grafikeinheiten", "Immer Linux als Betriebssystem"], "MPUs nutzen meist externen Speicher."),
   mc("Wofür wird ein großer SoC im Fahrzeug typischerweise genutzt?", ["Infotainment oder automatisiertes Fahren", "Fensterhebermotor", "Einfacher Temperatursensor", "Scheibenwischerrelais"], "Dort braucht man viel Rechenleistung."),
   mc("Was speichert der Flash?", ["Programm und Daten dauerhaft", "Nur Variablen während der Laufzeit", "Den Takt", "Analoge Spannungen"], "Er behält seinen Inhalt ohne Strom."),
   mc("Worauf sind Mikrocontroller optimiert?", ["Echtzeit und Zuverlässigkeit", "Videospiele", "Möglichst viel Arbeitsspeicher", "Internetbrowsen"], "Sie steuern direkt und vorhersagbar."),
   multi("Welche Blöcke zählen zur Peripherie?", ["Analog-Digital-Wandler", "CAN-Controller", "Timer", "Rechenkern"], [0, 1, 2], "Der Kern ist die CPU, keine Peripherie.")]),
 L("mcu.m1.l2", "Kerne, Takt und Rechenleistung", 6, [
  "Wie schnell ein Mikrocontroller arbeitet, hängt von mehreren Größen ab.",
  "## Takt",
  "Der Takt gibt an, wie viele Arbeitsschritte pro Sekunde möglich sind. Automotive-Mikrocontroller laufen typischerweise mit 100 MHz bis einige hundert MHz. Mehr Takt bedeutet mehr Leistung, aber auch mehr Stromverbrauch und Wärme.",
  "## Mehrere Kerne",
  "Viele moderne Controller haben mehrere Kerne. Sie teilen sich Aufgaben: etwa schnelle winkelsynchrone Motorfunktionen auf einem Kern, Kommunikation auf einem anderen. Dafür muss die Software sauber aufgeteilt und synchronisiert werden.",
  "## Architektur zählt",
  "Gleiche Taktzahl heißt nicht gleiche Leistung. Befehlssatz, Pipeline, Caches, Gleitkommaeinheit und Speicheranbindung bestimmen, wie viel ein Kern pro Takt schafft. Verbreitete Kernarchitekturen im Auto sind TriCore (Infineon), Arm Cortex-M und Cortex-R, Power Architecture (NXP, ST) und RH850 (Renesas)."],
  ["Takt: typisch 100 MHz bis einige hundert MHz.", "Mehrkern: Aufgaben verteilen, sauber synchronisieren.", "Architektur bestimmt Leistung pro Takt: TriCore, Arm, Power, RH850."],
  [S_INF, S_ST, S_REN],
  [card("Taktfrequenz", "Anzahl der Arbeitstakte pro Sekunde, z. B. 300 MHz."), card("TriCore", "Kernarchitektur von Infineon, Basis der AURIX-Familie."), card("Arm Cortex-R", "Arm-Kernfamilie für Echtzeit- und Sicherheitsanwendungen.")],
  [mc("Welche Kernarchitektur nutzt Infineon AURIX?", ["TriCore", "Cortex-A", "x86", "RISC-V ausschließlich"], "TriCore ist Infineons eigene Architektur."),
   mc("Was bedeutet mehr Takt neben mehr Leistung auch?", ["Mehr Strom und Wärme", "Weniger Speicher", "Weniger Pins", "Kein CAN mehr"], "Deshalb wird der Takt nicht beliebig erhöht."),
   mc("Warum ist gleiche Taktzahl nicht gleiche Leistung?", ["Architektur bestimmt Arbeit pro Takt", "Weil Takte unterschiedlich lang sind", "Weil Flash den Takt halbiert", "Weil CAN den Takt vorgibt"], "Pipeline, Caches und Befehlssatz zählen."),
   mc("Was ist eine Herausforderung bei Mehrkern-Controllern?", ["Software aufteilen und synchronisieren", "Kerne schmelzen", "Nur ein Kern darf rechnen", "Der Takt verdoppelt sich"], "Gemeinsame Daten brauchen Schutz."),
   mc("Welcher Bereich ist typisch für Automotive-MCU-Takte?", ["100 MHz bis einige hundert MHz", "1 bis 10 kHz", "5 bis 10 GHz", "Genau 1 MHz"], "PC-Prozessoren laufen mit mehreren GHz.")]),
 L("mcu.m1.l3", "Vom Reset bis zur Anwendung", 5, [
  "Was passiert, wenn ein Mikrocontroller Strom bekommt?",
  "## Hochlauf",
  "Nach dem Reset startet die Firmware an einer festen Adresse. Erst laufen Selbsttests und Grundeinstellungen: Takterzeugung (PLL), Speicherinitialisierung, Prüfung der Sicherheitsmechanismen. Oft prüft ein Sicherheitsmodul die Software (Secure Boot).",
  "## Bootloader und Anwendung",
  "Ein Bootloader entscheidet, ob die Anwendung startet oder neue Software geladen wird. Danach initialisiert die Anwendung Treiber und Betriebssystem und startet die Tasks.",
  "## Zeitkritisch",
  "In Fahrzeugen muss der Start schnell gehen: Manche Funktionen sollen wenige hundert Millisekunden nach dem Wecken bereit sein, etwa für Kommunikation auf dem Bus."],
  ["Reset → Firmware-Start → Selbsttests, PLL, Speicher.", "Secure Boot und Bootloader vor der Anwendung.", "Startzeit ist im Fahrzeug kritisch."],
  [S_INF],
  [card("PLL", "Phase-Locked Loop: erzeugt aus einem Quarztakt den hohen Systemtakt."), card("Reset", "Zustand, in dem der Controller neu startet.")],
  [order("Ordne den Hochlauf.", ["Reset", "Takt und Speicher initialisieren", "Software prüfen (Secure Boot)", "Bootloader entscheidet", "Anwendung startet"], "Erst Grundlagen, dann Prüfung, dann Anwendung."),
   mc("Was erzeugt die PLL?", ["Den hohen Systemtakt", "Die Versorgungsspannung", "Die CAN-Botschaften", "Den Flash-Inhalt"], "Aus einem Quarz wird ein schneller Takt."),
   mc("Warum ist die Startzeit im Fahrzeug wichtig?", ["Funktionen müssen schnell bereit sein", "Weil der Fahrer sonst aussteigt", "Wegen der Abgasnorm", "Weil Strom teuer ist"], "Etwa Busteilnahme kurz nach dem Wecken."),
   mc("Was entscheidet der Bootloader?", ["Anwendung starten oder neu laden", "Welche Musik läuft", "Wie schnell das Auto fährt", "Welche Sprache angezeigt wird"], "Er ist die Brücke zum Flashen."),
   mc("Wo startet die Firmware nach dem Reset?", ["An einer festen Adresse", "Zufällig im RAM", "Im Bus", "Im Sensor"], "Die Startadresse ist vom Chip vorgegeben.")])
])

M2 = M("mcu.m2", 1, "Was Automotive anders macht", "Temperatur, Qualifikation, Sicherheit, Lebensdauer und Verfügbarkeit.", [
 L("mcu.m2.l1", "Hitze, Kälte, Erschütterung", 6, [
  "Ein Chip im Motorraum erlebt Bedingungen, die ein Smartphone nie sieht.",
  "## Temperaturbereiche",
  "Die Qualifikationsnorm AEC-Q100 kennt Temperaturklassen: Grade 0 von −40 bis +150 °C, Grade 1 von −40 bis +125 °C, Grade 2 bis +105 °C, Grade 3 bis +85 °C. Motornahe Steuergeräte brauchen oft Grade 1 oder 0.",
  "## Weitere Belastungen",
  "Vibration, Temperaturwechsel, Feuchtigkeit, elektromagnetische Störungen und Spannungsspitzen im Bordnetz. Gehäuse, Lötstellen und Chip müssen das über viele Jahre aushalten.",
  "## Qualifikation",
  "AEC-Q100 beschreibt Belastungstests für integrierte Schaltungen: etwa Hochtemperatur-Lebensdauertests, Temperaturwechsel und Feuchte. Erst nach bestandener Qualifikation gilt ein Chip als automotive-tauglich. Ziel sind Fehlerraten im Bereich weniger Teile pro Million (ppm) oder besser."],
  ["AEC-Q100 Grade 0: −40…150 °C, Grade 1: −40…125 °C.", "Belastungen: Vibration, Temperaturwechsel, Feuchte, EMV, Spannungsspitzen.", "Qualifikation durch Belastungstests; Ziel: sehr niedrige ppm-Fehlerraten."],
  [S_AEC],
  [card("AEC-Q100", "Qualifikationsnorm des Automotive Electronics Council für integrierte Schaltungen."), card("Grade 1", "AEC-Q100-Temperaturklasse −40 bis +125 °C."), card("ppm", "Parts per Million: Fehler pro Million Bauteile.")],
  [mc("Welchen Bereich hat AEC-Q100 Grade 0?", ["−40 bis +150 °C", "0 bis +70 °C", "−40 bis +85 °C", "−20 bis +60 °C"], "Grade 1 reicht bis +125 °C."),
   mc("Was beschreibt AEC-Q100?", ["Belastungstests für Chips", "Abgasgrenzwerte", "Diagnosedienste", "Busprotokolle"], "Qualifikation integrierter Schaltungen."),
   multi("Welche Belastungen muss ein Automotive-Chip aushalten?", ["Vibration", "Temperaturwechsel", "Spannungsspitzen", "Ständiges Untertauchen im Meer"], [0, 1, 2], "Dauerhaft unter Wasser ist kein typisches Szenario."),
   mc("Welche Fehlerrate wird angestrebt?", ["Wenige ppm oder besser", "Etwa 10 Prozent", "Jedes zweite Teil", "Egal, Hauptsache billig"], "Bei Millionen Fahrzeugen zählt jedes Teil."),
   mc("Welche Klasse brauchen motornahe Steuergeräte oft?", ["Grade 1 oder 0", "Grade 3", "Consumer-Grade", "Keine Klasse"], "Dort wird es sehr heiß.")]),
 L("mcu.m2.l2", "Funktionale Sicherheit im Chip", 7, [
  "Steuern Mikrocontroller Bremse, Lenkung oder Antrieb, müssen sie Fehler in sich selbst erkennen. Viele Automotive-Controller werden für ISO 26262 bis ASIL D entwickelt.",
  "## Lockstep",
  "Zwei Kerne rechnen dasselbe, eine Vergleichslogik prüft jeden Takt. Weichen sie ab, wird ein Fehler gemeldet. So fallen zufällige Hardwarefehler auf, etwa durch Strahlung oder Alterung.",
  "## ECC und Speicherschutz",
  "Fehlerkorrigierende Codes (ECC) erkennen und korrigieren Bitfehler in Flash und RAM. Eine Memory Protection Unit (MPU) verhindert, dass Software unterschiedlicher Sicherheitsstufen sich gegenseitig stört.",
  "## Überwachung",
  "Spannungs- und Taktüberwachung, Watchdogs, Selbsttests beim Start und im Betrieb (etwa eingebaute Logiktests) und eine zentrale Fehlersammelstelle, die bei Bedarf einen sicheren Zustand auslöst. Der Hersteller liefert ein Safety Manual, das beschreibt, wie man die Mechanismen richtig nutzt."],
  ["Viele Controller für ISO 26262 bis ASIL D.", "Lockstep, ECC, Speicherschutz (MPU).", "Spannungs-/Taktüberwachung, Watchdog, Selbsttests, Safety Manual."],
  [S_26262, S_INF],
  [card("ECC", "Error Correcting Code: erkennt und korrigiert Bitfehler im Speicher."), card("MPU (Memory Protection Unit)", "Speicherschutz, der Zugriffe von Softwareteilen begrenzt."), card("Safety Manual", "Herstellerdokument, wie Sicherheitsmechanismen eines Chips zu nutzen sind.")],
  [mc("Was erkennt ein Lockstep-Kern?", ["Abweichungen zwischen zwei Rechnungen", "Falsche Busbotschaften", "Leere Batterien", "Falsche Lackfarbe"], "Zufällige Hardwarefehler fallen so auf."),
   mc("Was macht ECC?", ["Bitfehler erkennen und korrigieren", "Daten verschlüsseln", "Den Takt erhöhen", "Strom sparen"], "Error Correcting Code."),
   mc("Wozu dient eine Memory Protection Unit?", ["Softwareteile voneinander abschotten", "Speicher vergrößern", "Flash schneller machen", "Programme komprimieren"], "Rückwirkungsfreiheit zwischen ASIL-Stufen."),
   mc("Was beschreibt das Safety Manual?", ["Wie Sicherheitsmechanismen zu nutzen sind", "Wie man den Chip lötet", "Wie man Autos verkauft", "Wie man Abgas misst"], "Ohne richtige Nutzung kein Sicherheitsnachweis."),
   mc("Bis zu welcher Stufe werden viele Automotive-MCUs entwickelt?", ["ASIL D", "ASIL A", "QM", "SIL 4 ausschließlich"], "Die höchste Stufe der ISO 26262.")]),
 L("mcu.m2.l3", "Langlebig und lange lieferbar", 6, [
  "Ein Fahrzeug wird viele Jahre entwickelt, produziert und dann über ein Jahrzehnt gefahren. Ersatzteile müssen lange verfügbar sein.",
  "## Lebensdauer",
  "Steuergeräte sind oft für 15 Jahre und mehr ausgelegt, mit vielen tausend Betriebsstunden und Ruhezeiten. Flash muss Daten über diese Zeit halten (Data Retention) und viele Schreibzyklen für Lernwerte verkraften.",
  "## Verfügbarkeit",
  "Automotive-Chiphersteller sichern oft eine Lieferbarkeit über 10 bis 15 Jahre zu. Deshalb werden nicht immer die neuesten Fertigungstechnologien genutzt, sondern bewährte, die lange betrieben werden.",
  "## Die Chipkrise",
  "2020 bis 2022 fehlten weltweit Halbleiter. Autohersteller mussten Produktion stoppen, teils wegen einfacher Chips für wenige Euro. Seitdem planen Hersteller langfristiger, bauen Lagerbestände auf und arbeiten enger mit Chipherstellern zusammen."],
  ["Auslegung oft 15+ Jahre; Flash: Datenhaltung und Schreibzyklen.", "Lieferbarkeit 10–15 Jahre; bewährte Technologien.", "Chipkrise 2020–2022 führte zu langfristiger Planung."],
  [S_AEC, S_INF],
  [card("Data Retention", "Fähigkeit eines Speichers, Daten ohne Strom über Jahre zu halten."), card("Langzeitverfügbarkeit", "Zusage, ein Bauteil viele Jahre liefern zu können.")],
  [mc("Warum nutzen Automotive-Chips nicht immer die neueste Fertigung?", ["Bewährte Technik ist lange lieferbar", "Neue Technik ist verboten", "Autos brauchen keine Rechenleistung", "Neue Chips passen nicht ins Auto"], "Lange Lieferbarkeit und erprobte Qualität."),
   mc("Was bedeutet Data Retention?", ["Daten ohne Strom lange halten", "Daten schnell löschen", "Daten verschlüsseln", "Daten versenden"], "Wichtig für Flash über die Fahrzeuglebensdauer."),
   mc("Was zeigte die Chipkrise?", ["Auch billige Chips können Produktion stoppen", "Chips sind unwichtig", "Autos brauchen keine Chips", "Chips sind unbegrenzt verfügbar"], "Ein fehlendes Teil stoppt das ganze Fahrzeug."),
   mc("Wie lange sichern Hersteller oft Lieferbarkeit zu?", ["10 bis 15 Jahre", "6 Monate", "1 Jahr", "100 Jahre"], "Passend zur Fahrzeuglebensdauer."),
   mc("Was muss Flash für Lernwerte zusätzlich können?", ["Viele Schreibzyklen", "Schnell vergessen", "Nur einmal beschreibbar sein", "Ohne Strom löschen"], "Lernwerte werden regelmäßig aktualisiert.")])
])

M3 = M("mcu.m3", 2, "Infineon, ST, NXP, Renesas", "Die wichtigsten Familien für Steuergeräte und ihre Eigenschaften.", [
 L("mcu.m3.l1", "Infineon AURIX und TRAVEO", 7, [
  "Infineon gehört zu den größten Anbietern von Automotive-Mikrocontrollern. Die AURIX-Familie ist in Motor-, Getriebe-, Fahrwerks- und Sicherheitssteuergeräten weit verbreitet.",
  "## AURIX-Generationen",
  "TC2xx (erste Generation, 65 nm) mit bis zu drei TriCore-Kernen. TC3xx (zweite Generation, 40 nm) mit bis zu sechs Kernen und bis 300 MHz. TC4x (dritte Generation, 28 nm) mit schnelleren Kernen, einer Parallelverarbeitungseinheit (PPU) für Signalverarbeitung und KI-Aufgaben sowie Unterstützung für CAN XL und schnelles Ethernet.",
  "## Typische Merkmale",
  "Lockstep-Kerne für ASIL D, das Generic Timer Module (GTM) für winkelbasierte Motorfunktionen, Hardware-Sicherheitsmodul (HSM), viele CAN-FD-Kanäle, FlexRay, Ethernet und schnelle ADCs.",
  "## TRAVEO",
  "Mit der Übernahme von Cypress kam die TRAVEO-Familie auf Arm-Cortex-Basis hinzu, eingesetzt etwa in Karosserie, Kombiinstrument und Gateways.",
  "## Hinweis",
  "Produktdaten ändern sich mit jeder Generation. Für konkrete Projekte immer das aktuelle Datenblatt prüfen."],
  ["AURIX TC2xx 65 nm, TC3xx 40 nm, TC4x 28 nm.", "Merkmale: TriCore-Lockstep, GTM, HSM, viele Busse.", "TRAVEO (Arm) aus der Cypress-Übernahme."],
  [S_INF],
  [card("AURIX TC3xx", "Zweite AURIX-Generation (40 nm), bis zu sechs TriCore-Kerne."), card("AURIX TC4x", "Dritte AURIX-Generation (28 nm) mit PPU und CAN XL."), card("PPU", "Parallel Processing Unit: Vektorrechenwerk im AURIX TC4x für Signalverarbeitung und KI.")],
  [mc("In welcher Strukturgröße wird AURIX TC3xx gefertigt?", ["40 nm", "65 nm", "28 nm", "5 nm"], "TC2xx 65 nm, TC4x 28 nm."),
   mc("Was bringt der TC4x Neues mit?", ["Parallelverarbeitungseinheit (PPU)", "Keine Sicherheitsmechanismen", "Nur einen Kern", "Analoge Rechenwerke"], "Für Signalverarbeitung und KI-Aufgaben."),
   mc("Wofür ist das GTM im AURIX wichtig?", ["Winkelbasierte Motorfunktionen", "Displaysteuerung", "Bluetooth", "Musikwiedergabe"], "Etwa Einspritz- und Zündpulse."),
   mc("Woher stammt die TRAVEO-Familie?", ["Aus der Cypress-Übernahme", "Von ST", "Von Renesas", "Von NXP"], "Infineon übernahm Cypress 2020."),
   mc("Wie viele TriCore-Kerne hat ein großer TC3xx höchstens?", ["Sechs", "Einen", "Zwölf", "Hundert"], "Bis zu sechs Kerne bei bis zu 300 MHz.")], vol=True),
 L("mcu.m3.l2", "ST, NXP und Renesas", 7, [
  "Neben Infineon prägen drei weitere Anbieter den Markt.",
  "## STMicroelectronics",
  "ST hat mit SPC5 eine lange Linie auf Power-Architecture-Basis (teils gemeinsam mit NXP entwickelt), etwa für Motor- und Getriebesteuerung. Die neuere Stellar-Familie nutzt Arm-Cortex-R52-Kerne und wird zum Teil in 28 nm FD-SOI mit eingebettetem Phasenwechselspeicher (PCM) gefertigt, gedacht für zonale und domänenübergreifende Steuergeräte.",
  "## NXP",
  "NXP bietet Power-Architecture-Controller (MPC57xx) und die S32-Plattform: S32K für allgemeine Aufgaben (Cortex-M), S32E/S32Z für Echtzeit-Domänen (Cortex-R52), S32G als Netzwerkprozessor für Gateways und weitere Varianten.",
  "## Renesas",
  "Renesas ist mit der RH850-Familie stark, besonders bei japanischen Herstellern und in Fahrwerk und Antrieb. Varianten wie RH850/U2A in 28 nm bieten mehrere Kerne und Virtualisierung. Für Rechenaufgaben gibt es die R-Car-SoCs.",
  "## Gemeinsamkeiten",
  "Alle bieten Lockstep, ECC, Hardware-Sicherheitsmodule, AUTOSAR-Treiber und Werkzeugketten. Die Wahl hängt oft von Peripherie, Erfahrung, Lieferkette und Preis ab, nicht nur von der Rechenleistung."],
  ["ST: SPC5 (Power Architecture), Stellar (Cortex-R52, teils 28 nm FD-SOI mit PCM).", "NXP: MPC57xx, S32K/E/Z/G.", "Renesas: RH850 (z. B. U2A in 28 nm), R-Car."],
  [S_ST, S_NXP, S_REN],
  [card("Stellar", "ST-Mikrocontrollerfamilie mit Arm-Cortex-R52-Kernen, teils mit eingebettetem PCM."), card("S32G", "NXP-Netzwerkprozessor für Fahrzeug-Gateways."), card("RH850", "Renesas-Mikrocontrollerfamilie für Automotive-Anwendungen.")],
  [mc("Welche Kerne nutzt die ST-Stellar-Familie?", ["Arm Cortex-R52", "TriCore", "x86", "RH850"], "Für Echtzeit und funktionale Sicherheit."),
   mc("Welche NXP-Familie ist für Gateways gedacht?", ["S32G", "S32K", "MPC5554", "LPC800"], "Netzwerkprozessor mit vielen Schnittstellen."),
   mc("Welche Familie gehört zu Renesas?", ["RH850", "AURIX", "SPC5", "S32K"], "Dazu die R-Car-SoCs."),
   mc("Welchen Speicher nutzt ST in Teilen der Stellar-Familie?", ["Phasenwechselspeicher (PCM)", "Magnetband", "Lochkarten", "Nur ROM"], "Eingebettet in 28 nm FD-SOI."),
   mc("Wovon hängt die Wahl des Controllers oft ab?", ["Peripherie, Erfahrung, Lieferkette, Preis", "Nur vom Logo", "Nur von der Farbe", "Nur vom Takt"], "Rechenleistung ist nur ein Kriterium.")], vol=True),
 L("mcu.m3.l3", "Den richtigen Controller wählen", 6, [
  "Für ein neues Steuergerät wählt das Team einen Controller anhand vieler Kriterien.",
  "## Funktion",
  "Wie viel Rechenleistung, wie viele Kerne, wie viel Flash und RAM? Welche Peripherie wird gebraucht, etwa winkelbasierte Timer für Motoren, viele ADC-Kanäle, CAN FD, Ethernet, SENT oder PSI5 für Sensoren?",
  "## Sicherheit",
  "Welcher ASIL wird gefordert? Welche Security-Funktionen (HSM, Secure Boot, Schlüsselspeicher) braucht man für R155?",
  "## Projekt und Wirtschaft",
  "Preis pro Stück bei Millionenstückzahlen, Lieferbarkeit über die Laufzeit, Erfahrung im Team, vorhandene Software, Werkzeugkette, Unterstützung durch den Hersteller und Pin-Kompatibilität für spätere Varianten.",
  "## Reserven",
  "Software wächst während der Entwicklung. Viele Teams planen deshalb Reserven bei Laufzeit und Speicher ein, etwa 20 bis 30 Prozent."],
  ["Kriterien: Rechenleistung, Speicher, Peripherie.", "Sicherheit (ASIL) und Security (HSM).", "Preis, Lieferbarkeit, Werkzeuge, Erfahrung; Reserven einplanen."],
  [S_INF, S_NXP],
  [card("SENT", "Single Edge Nibble Transmission: digitale Sensorschnittstelle (SAE J2716)."), card("PSI5", "Peripheral Sensor Interface 5: Zweidraht-Sensorschnittstelle, z. B. für Airbag-Sensoren."), card("Pin-Kompatibilität", "Gleiche Gehäuse und Pinbelegung über mehrere Controller-Varianten.")],
  [multi("Welche Kriterien zählen bei der Controllerwahl?", ["Peripherie", "Lieferbarkeit", "ASIL-Eignung", "Lieblingsfarbe des Teams"], [0, 1, 2], "Farbe zählt nicht."),
   mc("Warum plant man Reserven bei Speicher und Laufzeit?", ["Software wächst während der Entwicklung", "Damit der Chip schwerer wird", "Weil Flash schrumpft", "Wegen der Abgasnorm"], "Typisch 20 bis 30 Prozent."),
   mc("Wofür ist SENT gedacht?", ["Digitale Sensorsignale", "Videoübertragung", "Software-Updates", "Diagnose über Ethernet"], "SAE J2716."),
   mc("Was bringt Pin-Kompatibilität?", ["Einfacher Wechsel auf andere Varianten", "Mehr Rechenleistung", "Bessere Abgaswerte", "Kürzere Kabel"], "Die Leiterplatte kann bleiben."),
   mc("Warum ist der Stückpreis so wichtig?", ["Millionenstückzahlen", "Weil Chips teurer als Autos sind", "Weil Kunden den Chip sehen", "Weil er die Leistung bestimmt"], "Cent-Beträge summieren sich.")])
])

M4 = M("mcu.m4", 2, "Was die Nanometer bedeuten", "Strukturgrößen, Vor- und Nachteile kleiner Knoten und warum Autos oft ältere nutzen.", [
 L("mcu.m4.l1", "Der Fertigungsknoten", 6, [
  "Angaben wie 40 nm oder 28 nm bezeichnen den Fertigungsknoten (Technologieknoten) eines Chips. Früher entsprach die Zahl ungefähr der Länge des Transistor-Gates. Heute ist sie eher ein Name für eine Technologiegeneration; ein 5-nm-Prozess hat keine Strukturen, die genau 5 nm messen.",
  "## Was kleiner bringt",
  "Kleinere Transistoren passen dichter auf den Chip. Bei gleicher Fläche gibt es mehr Logik, oder dieselbe Logik braucht weniger Fläche. Sie schalten schneller und brauchen pro Schaltvorgang weniger Energie. Das ermöglicht mehr Kerne, größere Speicher und höhere Takte.",
  "## Moores Gesetz",
  "Gordon Moore beobachtete 1965, dass sich die Zahl der Transistoren pro Chip regelmäßig verdoppelt (später meist mit etwa zwei Jahren angegeben). Dieser Trend trug Jahrzehnte, wird aber immer teurer und langsamer."],
  ["Nanometer-Angabe = Technologiegeneration, nicht mehr exakte Strukturgröße.", "Kleiner: dichter, schneller, weniger Energie pro Schaltvorgang.", "Moores Gesetz: Verdopplung der Transistorzahl, zunehmend teurer."],
  [S_INF, S_ST],
  [card("Fertigungsknoten", "Technologiegeneration der Chipfertigung, z. B. 40 nm oder 28 nm."), card("Moores Gesetz", "Beobachtung, dass sich die Transistorzahl pro Chip regelmäßig verdoppelt.")],
  [mc("Was bezeichnet die Nanometer-Angabe heute vor allem?", ["Eine Technologiegeneration", "Die exakte Gate-Länge", "Die Chipgröße", "Die Taktfrequenz"], "Der Name hat sich von der Messgröße gelöst."),
   mc("Was bringt ein kleinerer Knoten?", ["Mehr Transistoren auf gleicher Fläche", "Weniger Rechenleistung", "Höheren Stromverbrauch pro Schaltvorgang", "Größere Chips"], "Dichte, Geschwindigkeit, Effizienz."),
   mc("Was beschreibt Moores Gesetz?", ["Verdopplung der Transistorzahl", "Halbierung der Chippreise jedes Jahr", "Verdopplung des Takts jede Woche", "Abgasgrenzwerte"], "Eine Beobachtung von 1965."),
   mc("Hat ein 5-nm-Chip Strukturen von genau 5 nm?", ["Nein, es ist ein Generationsname", "Ja, immer", "Nur die Pins", "Nur das Gehäuse"], "Die Zahl ist heute eher Marketing."),
   mc("Warum verlangsamt sich Moores Gesetz?", ["Es wird immer teurer und schwieriger", "Weil es verboten wurde", "Weil Silizium knapp ist", "Weil niemand mehr Chips braucht"], "Physik und Kosten setzen Grenzen.")]),
 L("mcu.m4.l2", "Warum Autos ältere Knoten nutzen", 7, [
  "Smartphone-Chips werden in 3 bis 5 nm gefertigt, viele Automotive-Mikrocontroller dagegen in 40, 65 oder 90 nm, neuere in 28 nm. Das hat gute Gründe.",
  "## Eingebetteter Flash",
  "Mikrocontroller brauchen Flash direkt auf dem Chip. Klassischer eingebetteter Flash lässt sich unter etwa 28 nm kaum noch wirtschaftlich herstellen. Deshalb setzen neue Generationen auf andere nichtflüchtige Speicher: Phasenwechselspeicher (PCM), magnetischen Speicher (MRAM) oder resistiven Speicher (RRAM).",
  "## Robustheit und Spannung",
  "Ältere Knoten vertragen höhere Spannungen und Temperaturen besser, haben weniger Leckströme bei Hitze und sind über lange Zeit erprobt. Für Grade-0- oder Grade-1-Anwendungen ist das ein Vorteil.",
  "## Kosten und Lieferbarkeit",
  "Masken und Entwicklung für kleine Knoten kosten sehr viel. Für einen Controller mit moderatem Rechenbedarf lohnt sich das oft nicht. Ältere Fabriken laufen lange und sichern Lieferbarkeit.",
  "## Wo kleine Knoten im Auto doch stecken",
  "Große SoCs für Infotainment, Zentralrechner und automatisiertes Fahren werden in modernen Knoten (etwa 7 nm und kleiner) gefertigt, weil sie enorme Rechenleistung brauchen."],
  ["Viele Automotive-MCUs: 90/65/40 nm, neuere 28 nm; Smartphones 3–5 nm.", "Eingebetteter Flash endet etwa bei 28 nm → PCM, MRAM, RRAM.", "Ältere Knoten: robust, günstig, lange lieferbar; SoCs für ADAS in modernen Knoten."],
  [S_INF, S_ST, S_NXP],
  [card("eFlash", "Eingebetteter Flash-Speicher auf dem Mikrocontroller-Chip."), card("PCM", "Phase-Change Memory: nichtflüchtiger Speicher auf Basis eines Materials, das zwischen amorph und kristallin wechselt."), card("MRAM", "Magnetoresistiver Speicher: speichert über magnetische Ausrichtung."), card("RRAM", "Resistiver Speicher: speichert über veränderbaren Widerstand.")],
  [mc("Warum wechseln neue MCU-Generationen zu PCM, MRAM oder RRAM?", ["Eingebetteter Flash skaliert kaum unter 28 nm", "Flash ist verboten", "Weil RAM zu langsam ist", "Weil Kunden es wünschen"], "Neue nichtflüchtige Speicher passen zu kleineren Knoten."),
   mc("Was ist ein Vorteil älterer Knoten im Auto?", ["Robust bei Hitze und Spannung", "Höchste Rechenleistung", "Geringste Fläche", "Neueste Technik"], "Weniger Leckströme, lange erprobt."),
   mc("Wo werden sehr moderne Knoten im Auto genutzt?", ["In SoCs für ADAS und Infotainment", "In Fensterhebern", "In Glühlampen", "In Sicherungen"], "Dort zählt Rechenleistung."),
   mc("In welchem Knoten werden viele neue Automotive-MCUs gefertigt?", ["28 nm", "3 nm", "180 nm", "1 µm"], "Etwa AURIX TC4x, Stellar, RH850/U2A."),
   mc("Was ist ein Kostenfaktor kleiner Knoten?", ["Sehr teure Masken und Entwicklung", "Billigere Fabriken", "Weniger Ingenieure", "Kein Testaufwand"], "Lohnt sich nur bei großem Rechenbedarf.")], vol=True),
 L("mcu.m4.l3", "Transistoren: planar, FD-SOI, FinFET", 6, [
  "Mit kleiner werdenden Strukturen musste sich auch die Bauform der Transistoren ändern.",
  "## Planar",
  "Klassische Transistoren liegen flach im Silizium. Unterhalb von etwa 28 nm wird es schwer, den Kanal zuverlässig abzuschalten; Leckströme steigen.",
  "## FD-SOI",
  "Fully Depleted Silicon on Insulator: Der Transistor sitzt auf einer dünnen Siliziumschicht über einer isolierenden Oxidschicht. Das senkt Leckströme und erlaubt, Eigenschaften über die Rückseite zu verstellen (Body Biasing). ST nutzt FD-SOI unter anderem für Teile der Stellar-Familie.",
  "## FinFET",
  "Der Kanal ragt als dünne Finne aus dem Silizium, das Gate umschließt ihn von drei Seiten. Das ermöglicht Knoten von 16 nm abwärts. Die neueste Generation nutzt Gate-All-Around-Transistoren, bei denen das Gate den Kanal vollständig umschließt.",
  "## Für die Praxis",
  "Für Software-Entwicklerinnen und -Entwickler bleibt das meist unsichtbar. Es erklärt aber, warum neue Controller sparsamer, schneller oder mit neuen Speichertechnologien kommen."],
  ["Planar bis etwa 28 nm; darunter steigen Leckströme.", "FD-SOI: isolierende Schicht, wenig Leckstrom, Body Biasing.", "FinFET ab 16 nm; danach Gate-All-Around."],
  [S_ST],
  [card("FD-SOI", "Fully Depleted Silicon on Insulator: Transistoren auf dünnem Silizium über einer Isolierschicht."), card("FinFET", "Transistor mit finnenförmigem Kanal, vom Gate dreiseitig umschlossen."), card("Gate-All-Around", "Transistor, bei dem das Gate den Kanal vollständig umschließt.")],
  [mc("Was ist das Besondere an FD-SOI?", ["Eine isolierende Schicht unter dem Transistor", "Der Kanal ist eine Finne", "Es gibt kein Gate", "Es ist ein Speicher"], "Senkt Leckströme."),
   mc("Was umschließt das Gate bei FinFETs?", ["Den Kanal von drei Seiten", "Den ganzen Chip", "Nur die Pins", "Den Flash"], "Bessere Kontrolle über den Kanal."),
   mc("Was ist das Problem planarer Transistoren unter etwa 28 nm?", ["Steigende Leckströme", "Zu wenig Fläche", "Zu niedrige Spannung", "Zu viel Kupfer"], "Der Kanal lässt sich schlecht abschalten."),
   mc("Was erlaubt Body Biasing?", ["Transistoreigenschaften nachträglich verstellen", "Den Chip verbiegen", "Mehr Pins", "Längere Kabel"], "Über die Rückseite der Isolierschicht."),
   mc("Welche Bauform folgt auf FinFET?", ["Gate-All-Around", "Planar", "Röhren", "Relais"], "Das Gate umschließt den Kanal vollständig.")])
])

M5 = M("mcu.m5", 3, "Speicher und Peripherie im Detail", "Flash und Wartezyklen, Datenflash, Timer, ADC und Schnittstellen.", [
 L("mcu.m5.l1", "Programmflash, Datenflash, RAM", 6, [
  "Speicher ist im Mikrocontroller in mehrere Bereiche geteilt.",
  "## Programmflash",
  "Enthält Code und Kalibrierdaten, meist mehrere Megabyte. Flash ist langsamer als der Kern; bei hohem Takt braucht ein Zugriff mehrere Wartezyklen. Caches und Prefetch-Puffer überbrücken das.",
  "## Datenflash",
  "Ein separater Bereich für häufig geänderte Daten wie Lernwerte und Fehlerspeicher. Er verkraftet mehr Schreibzyklen. Software emuliert darauf oft ein EEPROM.",
  "## RAM",
  "Schneller Arbeitsspeicher, oft verteilt: lokale Speicher nahe jedem Kern (schnell) und gemeinsamer Speicher (für Datenaustausch). Wo Variablen liegen, beeinflusst die Laufzeit stark.",
  "## Zwei Bänke",
  "Manche Controller haben zwei Flash-Bänke: Eine läuft, die andere wird im Hintergrund beschrieben. Das ermöglicht Updates ohne lange Ausfallzeit (A/B-Swap)."],
  ["Programmflash: Code und Kalibrierdaten; Wartezyklen, Caches.", "Datenflash: Lernwerte, Fehlerspeicher, EEPROM-Emulation.", "RAM lokal und gemeinsam; zwei Flash-Bänke für Updates."],
  [S_INF],
  [card("Wartezyklus (Wait State)", "Zusätzlicher Takt, den ein langsamer Speicherzugriff braucht."), card("EEPROM-Emulation", "Software, die auf Datenflash ein byteweise beschreibbares EEPROM nachbildet."), card("Lokaler RAM", "Schneller Speicher direkt an einem Kern.")],
  [mc("Was überbrückt die Langsamkeit des Flash?", ["Caches und Prefetch", "Mehr Pins", "Ein größeres Gehäuse", "Ein langsamerer Takt der Busse"], "So muss der Kern seltener warten."),
   mc("Wo liegen Lernwerte typischerweise?", ["Im Datenflash", "Im Programmflash neben dem Code", "Nur im RAM", "Im ADC"], "Der Datenflash verträgt mehr Schreibzyklen."),
   mc("Warum ist lokaler RAM wichtig für die Laufzeit?", ["Zugriffe sind dort am schnellsten", "Er ist größer", "Er ist nichtflüchtig", "Er ist verschlüsselt"], "Gemeinsamer Speicher ist langsamer erreichbar."),
   mc("Wozu dienen zwei Flash-Bänke?", ["Update im Hintergrund", "Doppelte Rechenleistung", "Zwei Betriebssysteme gleichzeitig", "Mehr CAN-Kanäle"], "A/B-Swap."),
   mc("Was ist ein Wartezyklus?", ["Zusätzlicher Takt für langsamen Zugriff", "Eine Pause im Fahrzeug", "Ein Fehlercode", "Ein Bootloader-Schritt"], "Typisch bei Flash und hohem Takt.")]),
 L("mcu.m5.l2", "Timer und ADC", 6, [
  "Für Motor- und Antriebssteuerungen sind Timer und Analog-Digital-Wandler die wichtigste Peripherie.",
  "## Timer",
  "Timer messen Zeiten zwischen Flanken (etwa Zahnzeiten des Kurbelwellensignals) und erzeugen Pulse (etwa PWM oder Einspritzimpulse). Komplexe Timer-Module wie das GTM in AURIX arbeiten weitgehend selbstständig und entlasten die Kerne.",
  "## ADC",
  "Analog-Digital-Wandler wandeln Spannungen in Zahlen, typischerweise mit 12 Bit Auflösung (4.096 Stufen). Wichtig sind Wandlungszeit, Genauigkeit und die Möglichkeit, Messungen zeitgenau oder winkelsynchron auszulösen, etwa genau beim Zahn X der Kurbelwelle.",
  "## Spezielle Wandler",
  "Delta-Sigma-Wandler erreichen hohe Auflösung, etwa für Stromsensoren in E-Motoren oder Klopfsignale. Viele Controller bieten außerdem Vergleicher (Komparatoren) für schnelle Schutzabschaltungen."],
  ["Timer messen Flanken und erzeugen Pulse; GTM arbeitet selbstständig.", "ADC typisch 12 Bit; Auslösen zeit- oder winkelsynchron.", "Delta-Sigma für hohe Auflösung; Komparatoren für Schutz."],
  [S_INF, S_REIF],
  [card("12-Bit-ADC", "Analog-Digital-Wandler mit 4.096 Stufen."), card("Delta-Sigma-Wandler", "Wandler mit Überabtastung für hohe Auflösung."), card("PWM", "Pulsweitenmodulation: Leistung über das Verhältnis von Ein- zu Gesamtzeit.")],
  [num("Wie viele Stufen hat ein 12-Bit-ADC?", 4096, "", 0, "2 hoch 12 = 4.096."),
   num("Ein 12-Bit-ADC mit 5 V Referenz: Wie viele Millivolt entspricht eine Stufe ungefähr?", 1.22, "mV", 0.02, "5.000 mV ÷ 4.096 ≈ 1,22 mV."),
   mc("Was entlastet ein Timer-Modul wie das GTM?", ["Die Rechenkerne", "Den Kraftstofftank", "Die Batterie", "Den CAN-Bus"], "Es arbeitet weitgehend selbstständig."),
   mc("Warum löst man ADC-Messungen winkelsynchron aus?", ["Messwerte passen zur Kurbelstellung", "Um Strom zu sparen", "Weil der ADC sonst kaputt geht", "Für die Diagnose über OBD"], "Etwa Saugrohrdruck zum richtigen Zeitpunkt."),
   mc("Wofür eignen sich Delta-Sigma-Wandler besonders?", ["Hohe Auflösung, z. B. Stromsensoren", "Sehr schnelle Schalter", "Busübertragung", "Software-Updates"], "Etwa in E-Motor-Umrichtern.")]),
 L("mcu.m5.l3", "Kommunikationsschnittstellen", 5, [
  "Ein Automotive-Controller spricht viele Sprachen.",
  "## Fahrzeugbusse",
  "Mehrere CAN-FD-Kanäle, LIN, bei vielen FlexRay, zunehmend Ethernet (100 Mbit/s bis 1 Gbit/s, teils mit Switch auf dem Chip) und bei neuesten Generationen CAN XL.",
  "## Lokale Schnittstellen",
  "SPI verbindet den Controller mit Bausteinen auf derselben Platine: Treiber-ICs für Endstufen, Überwachungsbausteine, Speicher. SENT und PSI5 bringen digitale Sensorsignale. I²C findet man seltener.",
  "## Debug",
  "Über Debug- und Trace-Schnittstellen beobachten Entwickler den Controller in Echtzeit, setzen Haltepunkte und zeichnen den Programmablauf auf. In Serie sind diese Zugänge gesperrt oder per Authentisierung geschützt."],
  ["Fahrzeugbusse: CAN FD, LIN, FlexRay, Ethernet, CAN XL.", "Lokal: SPI für ICs, SENT/PSI5 für Sensoren.", "Debug/Trace in Serie gesperrt oder geschützt."],
  [S_INF, S_BUS],
  [card("SPI", "Serial Peripheral Interface: schnelle serielle Verbindung zu Bausteinen auf der Platine."), card("Trace", "Aufzeichnung des Programmablaufs in Echtzeit für Analyse und Optimierung.")],
  [mc("Womit spricht der Controller mit Endstufen-ICs auf der Platine?", ["SPI", "FlexRay", "Ethernet", "LIN"], "SPI ist die typische lokale Verbindung."),
   mc("Was erlaubt Trace?", ["Programmablauf in Echtzeit aufzeichnen", "Software flashen ohne Tester", "Fahrzeug orten", "Abgas messen"], "Wichtig für Laufzeitanalysen."),
   mc("Warum sperrt man Debug-Zugänge in Serie?", ["Gegen Auslesen und Manipulation", "Damit der Chip kühler bleibt", "Wegen der Abgasnorm", "Damit CAN schneller ist"], "Debug ist ein mächtiger Angriffspunkt."),
   mc("Was kommt bei den neuesten Controllern als Bus hinzu?", ["CAN XL", "Parallelport", "Diskette", "Serielle Maus"], "Etwa beim AURIX TC4x."),
   mc("Wofür nutzt man PSI5?", ["Digitale Sensorsignale", "Videos", "Software-Updates", "Klimasteuerung per Funk"], "Etwa für Airbag-Sensoren.")])
])

M6 = M("mcu.m6", 3, "Software auf dem Controller", "Treiber, Mehrkern-Software, Laufzeit und Werkzeuge.", [
 L("mcu.m6.l1", "MCAL und Startcode", 5, [
  "Zwischen Hardware und Anwendung liegt eine dünne, aber wichtige Schicht.",
  "## MCAL",
  "Der Microcontroller Abstraction Layer in AUTOSAR enthält Treiber für ADC, Timer, CAN, SPI, Flash und mehr. Chiphersteller liefern meist eigene MCAL-Pakete, die zum jeweiligen Controller passen.",
  "## Konfiguration",
  "Die MCAL wird über Werkzeuge konfiguriert: Takte, Pinbelegung, Kanäle, Interrupts. Daraus entsteht Code. Fehler hier wirken sich auf alles darüber aus.",
  "## Startcode",
  "Ein kleiner Teil vor dem Betriebssystem stellt Stack, Speicher und Takt ein und ruft dann die Initialisierung auf. Er ist oft in Assembler oder sehr nah an der Hardware geschrieben."],
  ["MCAL: Hardwaretreiber in AUTOSAR, meist vom Chiphersteller.", "Konfiguration über Werkzeuge erzeugt Code.", "Startcode stellt Stack, Speicher und Takt ein."],
  [S_AUTOSAR],
  [card("MCAL", "Microcontroller Abstraction Layer: unterste AUTOSAR-Schicht mit Hardwaretreibern."), card("Startcode", "Code, der vor dem Betriebssystem Stack, Speicher und Takt vorbereitet.")],
  [mc("Wer liefert meist die MCAL?", ["Der Chiphersteller", "Der Fahrer", "Die Werkstatt", "Die Versicherung"], "Passend zum Controller."),
   mc("Wie wird die MCAL eingestellt?", ["Über Konfigurationswerkzeuge", "Per Hand am Lötkolben", "Über das Radio", "Gar nicht"], "Daraus entsteht Code."),
   mc("Was macht der Startcode?", ["Stack, Speicher und Takt einstellen", "Fehler löschen", "Musik abspielen", "CAN-Botschaften verschlüsseln"], "Vor dem Betriebssystem."),
   mc("Welche Treiber gehören zur MCAL?", ["ADC, Timer, CAN, SPI", "Navigation, Radio", "Sitzheizung, Spiegel", "Abgasgrenzwerte"], "Hardwarenahe Treiber."),
   mc("Warum sind Konfigurationsfehler in der MCAL kritisch?", ["Alles darüber baut darauf auf", "Weil sie gelb leuchten", "Weil sie Benzin kosten", "Weil sie unsichtbar sind"], "Ein falscher Takt betrifft das ganze System.")]),
 L("mcu.m6.l2", "Mehrkern-Software und Laufzeit", 7, [
  "Mehrere Kerne bringen Leistung, aber auch neue Fehlerquellen.",
  "## Aufteilung",
  "Tasks werden Kernen fest zugeordnet. Gute Aufteilungen halten zusammengehörige Daten auf einem Kern und minimieren Austausch. Sicherheitsrelevante Software läuft oft auf einem Lockstep-Kern.",
  "## Gemeinsame Daten",
  "Greifen zwei Kerne gleichzeitig auf dieselben Daten zu, drohen inkonsistente Werte. Lösungen sind Spinlocks, Nachrichtenpuffer oder doppelte Puffer, bei denen immer ein vollständiger Datensatz gelesen wird.",
  "## Laufzeit messen",
  "Jede Task muss in ihrem Zeitraster fertig werden, auch im schlimmsten Fall. Man misst Laufzeiten mit Trace, schätzt die Worst-Case Execution Time (WCET) und prüft die Auslastung jedes Kerns. Bei hohen Motordrehzahlen kann die winkelsynchrone Last schnell steigen.",
  "## Typische Probleme",
  "Zugriffskonflikte auf Speicher, Cache-Effekte, unerwartete Interrupt-Last und Prioritätsinversion. Viele Fehler zeigen sich nur sporadisch."],
  ["Tasks fest Kernen zuordnen; Austausch minimieren.", "Gemeinsame Daten schützen: Spinlocks, Puffer.", "Laufzeit messen, WCET schätzen, Auslastung prüfen."],
  [S_AUTOSAR, S_INF],
  [card("WCET", "Worst-Case Execution Time: längste mögliche Laufzeit eines Programmteils."), card("Spinlock", "Sperre, bei der ein Kern wartet, bis ein anderer den Zugriff freigibt."), card("Prioritätsinversion", "Hoch priorisierte Task wartet auf eine niedrig priorisierte, die eine Ressource hält.")],
  [mc("Was ist die WCET?", ["Längste mögliche Laufzeit", "Durchschnittliche Laufzeit", "Kürzeste Laufzeit", "Startzeit des Controllers"], "Muss ins Zeitraster passen."),
   mc("Wozu dient ein Spinlock?", ["Gleichzeitigen Zugriff verhindern", "Kerne beschleunigen", "Flash löschen", "Busse wecken"], "Ein Kern wartet auf die Freigabe."),
   mc("Was ist Prioritätsinversion?", ["Wichtige Task wartet auf unwichtige", "Tasks laufen rückwärts", "Kerne tauschen Plätze", "Der Takt halbiert sich"], "Klassisches Echtzeitproblem."),
   mc("Warum hält man zusammengehörige Daten auf einem Kern?", ["Weniger teurer Austausch", "Weil andere Kerne nicht lesen können", "Für die Optik", "Wegen der Abgasnorm"], "Kernübergreifende Zugriffe kosten Zeit."),
   mc("Wann steigt die winkelsynchrone Last besonders?", ["Bei hohen Drehzahlen", "Im Stand", "Bei Kälte", "Beim Tanken"], "Mehr Segmente pro Sekunde.")]),
 L("mcu.m6.l3", "Werkzeuge der Entwicklung", 5, [
  "Hinter jedem Steuergerät steht eine Werkzeugkette.",
  "## Compiler",
  "Für sicherheitsrelevante Software werden qualifizierte Compiler genutzt, die nach Normen wie ISO 26262 bewertet sind. Bekannte Anbieter liefern Compiler für TriCore, Arm, Power und RH850.",
  "## Debugger und Trace",
  "Hardware-Debugger verbinden sich über die Debug-Schnittstelle, erlauben Haltepunkte, Speicherzugriff und Trace. Für Messen und Kalibrieren im laufenden Betrieb nutzt man XCP.",
  "## Statische Analyse",
  "Werkzeuge prüfen Code auf Regeln wie MISRA C, finden potenzielle Laufzeitfehler und berechnen Speicher- und Stackbedarf.",
  "## Simulation",
  "Virtuelle Steuergeräte simulieren Controller und Peripherie am PC. So lässt sich Software testen, bevor Hardware verfügbar ist."],
  ["Qualifizierte Compiler für Sicherheitssoftware.", "Debugger, Trace und XCP.", "Statische Analyse (z. B. MISRA C) und virtuelle Steuergeräte."],
  [S_26262, S_ASAM],
  [card("MISRA C", "Regelwerk für sicheren C-Code im Automotive-Umfeld."), card("Virtuelles Steuergerät", "Simulation von Controller und Peripherie am PC zum frühen Testen.")],
  [mc("Was prüft MISRA C?", ["Regeln für sicheren C-Code", "Abgaswerte", "Busbitraten", "Reifenprofile"], "Ein verbreitetes Regelwerk."),
   mc("Was erlaubt ein virtuelles Steuergerät?", ["Software testen ohne Hardware", "Fahren ohne Motor", "Tanken ohne Kraftstoff", "Flashen ohne Software"], "Früh in der Entwicklung."),
   mc("Warum braucht man qualifizierte Compiler?", ["Für sicherheitsrelevante Software", "Weil sie schneller tippen", "Für bessere Grafik", "Für Musik"], "Fehler im Compiler wären fatal."),
   mc("Womit misst und kalibriert man im laufenden Betrieb?", ["XCP", "MISRA", "SPI", "ODX"], "Mess- und Kalibrierprotokoll."),
   mc("Was berechnen Analysewerkzeuge zusätzlich?", ["Speicher- und Stackbedarf", "Den Kaufpreis", "Die Lackdicke", "Den Kraftstoffverbrauch"], "Wichtig für Reserven.")])
])

